CREATE OR REPLACE PROCEDURE sp(
    para_Budget_invested_percent VARCHAR2,
    para_total_budget_percent_budgeted NUMBER,
    para_Mascot VARCHAR2,
    para_Location VARCHAR2
) AS
    CURSOR c_budget IS
        SELECT * FROM "budget" FOR UPDATE;
    CURSOR c_school IS
        SELECT * FROM "School" FOR UPDATE;
BEGIN
    FOR b IN c_budget LOOP
        IF b."Budget_invested_percent" = para_Budget_invested_percent
           AND b."Budgeted" > b."Invested" THEN
            UPDATE "budget"
               SET "total_budget_percent_budgeted" = para_total_budget_percent_budgeted
             WHERE CURRENT OF c_budget;
        END IF;
    END LOOP;

    FOR s IN c_school LOOP
        IF s."Mascot" = para_Mascot THEN
            UPDATE "School" SET "Location" = para_Location WHERE CURRENT OF c_school;
            IF s."IHSAA_Football_Class" = 'AAAA' THEN
                UPDATE "School" SET "Location" = para_Location || ' (AAAA)' WHERE CURRENT OF c_school;
            END IF;
        END IF;
    END LOOP;
END sp;

